// ✅ Validate — fail fast, before any Zoho call.
const b = $json.body || $json;
const itemId = String(b.item_id || '').trim();
const sku    = String(b.sku || '').trim();
const target = parseFloat(b.target);
const maxDel = parseFloat(b.max_delta) || 50;
const reason = String(b.reason || 'Physical count').slice(0, 200);
// Free text for the adjustment DESCRIPTION. It must never reach `reason`:
// Zoho's Reason is a managed dropdown and every distinct string becomes a
// permanent entry in it (we polluted it with one per picker before
// 2026-08-14). Description is per-record free text and creates nothing.
const picker = String(b.picker || '').trim().slice(0, 60);

if (!itemId)                    throw new Error('Missing item_id');
if (!isFinite(target))          throw new Error('target must be a number');
if (target < 0 || target > 10000) throw new Error(`target ${target} outside sanity bounds [0, 10000]`);

return [{ json: { itemId, sku, target, maxDel, reason, picker } }];

// 🧮 Read Zoho's CURRENT stock, then turn the target into a DELTA.
//
// ⚠ THIS IS WHY THE PROXY READS BEFORE IT WRITES. Zoho's adjustment API takes
// `quantity_adjusted` — a CHANGE, not a new total. Computing that change in
// Apps Script against the Zoho Stock mirror would use a number up to two
// minutes old, and any sale in that window would land a wrong correction.
// Read and write inside ONE execution and the arithmetic is against live data.
const v    = $('✅ Validate Input').first().json;
const item = $json.item || {};
const before = parseFloat(item.stock_on_hand);

if (!isFinite(before)) {
  throw new Error('Could not read stock_on_hand for item ' + v.itemId + ' — refusing to adjust blind');
}

const delta = +(v.target - before).toFixed(4);

// Already correct is a SUCCESS, not a failure — and the most common answer.
if (delta === 0) {
  return [{ json: { noop: true, before, target: v.target, delta: 0, sku: v.sku,
                    name: item.name || '',
                    message: `${v.sku || v.itemId} already at ${before} — nothing to adjust` } }];
}

// ⚠ Enforced HERE as well as in Apps Script. A guard that lives only in the
// caller is a guard that a future caller forgets.
if (Math.abs(delta) > v.maxDel) {
  throw new Error(
    `Refusing: ${v.sku || v.itemId} would move ${delta > 0 ? '+' : ''}${delta} ` +
    `(${before} → ${v.target}), beyond the ${v.maxDel} limit. ` +
    `A swing this size is far more likely a miscount or the wrong SKU than a real ` +
    `discrepancy, and it reaches eBay within minutes. Re-count, or force it deliberately.`);
}

return [{ json: { noop: false, before, target: v.target, delta, sku: v.sku,
                  itemId: v.itemId, reason: v.reason, name: item.name || '' } }];

// 📤 Report what actually moved — before, after, and Zoho's own record id.
const d = $('🧮 Compute Delta').first().json;
if (d.noop) return [{ json: { ok: true, noop: true, ...d } }];

const adj = ($json.inventory_adjustment) || {};
return [{ json: {
  ok: true,
  noop: false,
  sku: d.sku,
  name: d.name,
  before: d.before,
  after: d.target,
  delta: d.delta,
  adjustment_id: adj.inventory_adjustment_id || '',
  message: `${d.sku || d.itemId}: ${d.before} → ${d.target} (${d.delta > 0 ? '+' : ''}${d.delta})`
} }];
